import{_ as a,c as t,a2 as e,o as r}from"./chunks/framework.CqbvlPrP.js";const m=JSON.parse('{"title":"多空转换的临界条件是什么？","description":"","frontmatter":{},"headers":[],"relativePath":"stock/不预测/不预测理解.md","filePath":"stock/不预测/不预测理解.md"}'),o={name:"stock/不预测/不预测理解.md"};function n(s,p,c,i,d,_){return r(),t("div",null,p[0]||(p[0]=[e('<h1 id="多空转换的临界条件是什么" tabindex="-1">多空转换的临界条件是什么？ <a class="header-anchor" href="#多空转换的临界条件是什么" aria-label="Permalink to &quot;多空转换的临界条件是什么？&quot;">​</a></h1><p>首先，请记住一点，市场不可预测，只有行情过后，才能看清趋势。在此之前，我们所做的全部工作，与其说是识别趋势，不如说是在假设趋势，依据假设，决定如何交易，然后观察我们的假设是否被市场验证----这才是正确的投机观。</p><p>虽说单周期中的一段上涨趋势，可能是更大周期里的修正或回调，但是，就单独一个周期而论，那确实是它的上涨趋势，一样能让我们赚钱。。这里不过多讨论多周期，就按照单周期说说---趋势开始，进场交易，趋势终结，交易结束。（忘了插句嘴：一个周期中，顶底永远只有一个，不要摸顶抄底，除非天选之人，摸顶抄底非正途）。</p><p>干货开始------</p><p>一.识别趋势的启动，方法有3（方法千千万，这里只谈我个人经验，不喜勿喷）----</p><p>1.K线图形形态+K线组合or反转K+关键位:</p><p>反转图形：双顶/双底，头肩顶/底（M头/W底）等等..</p><p>a.双重顶/底为例：</p><p>b.再以头肩顶/底为例：</p><p>反转的K线组合：Pinbar（锤形线/流星线），吞没（看涨吞没/看跌吞没），等等..</p><p>已Pinbar(锤形线/流星线)为例：</p><p>关键价位：主要支撑压力位（a.同一个价格或很小的价格区间，被触及的次数越多越好；b.一眼就能看到，而不是刻意去画线；c.既做过压力位也做过支撑位，就是完成过支阻互换的价格或很小的价格区间。以上3个条件不一定全部满足，但满足的越多越好，胜率越高）</p><p>以上三个要素组合起来，相互印证，就可以成为你假设新趋势启动的理由：</p><p>如：</p><p>双重顶的右顶是K线看跌吞没形态+颈线位置正好是关键价位+突破颈线的K是个Pinbar，</p><p>然后带好止损，进场！</p><p>这种成功的概率高吗？肯定比你瞎做要高。</p><p>但更稳妥的使用方式还是在更大周期趋势回调中使用（如日线明显是下跌走势，那么就去4H或1H中上涨走势中做反转。）</p><p>2.趋势线123法则：</p><p>简单说下123代表的含义：</p><p>1:突破趋势线</p><p>2:回调不再破之前趋势的极值</p><p>3.突破前高或前低。</p><p>如图：</p><p>以最新的甲醇为例，4H图：</p><p>突破虚线3，假设4H甲醇反转下跌；上涨突破2，放弃看跌。 形态有3个可以进场位置，各点进场所面临的胜率，利润空间各有不同。</p><p>如图：</p><p>123法则做反转胜率高吗？不是太高，但一定有胜率高的高手！</p><p>如何正确使用123法则？</p><p>但更稳妥的使用方式还是在更大周期趋势回调中使用（如日线明显是下跌走势，那么就去4H或1H中上涨走势中做反转。） 还是上面甲醇的例子，眼光放大点，日线目前走的是上涨趋势中的宽幅箱体震荡：</p><p>甲醇日线 如果真要使用123法则，不妨等K线走到箱体下边缘，再在4H周期里做下降趋势的123：</p><p>意思依然是顺着大周期而做。。。</p><p>3.均线判断：</p><p>我依然认为均线是指标之王，虽然有滞后的弊端，但不妨碍指导它趋势启动的锚点。</p><p>假设用2条均线来看一段趋势的开始到结束（上涨为例）：</p><p>K线破快线，然后破慢线→快线金叉慢线开始多头排列→</p><p>K线站上快线，2均线距离扩大→动能下降，K线下破快线→</p><p>2均线聚拢→均线死叉。。。。。循环。</p><p>就以这个最简单的例子：</p><p>大家的交易系统是什么？敢不敢分享？ 172 赞同 · 16 评论回答</p><p>本人的周期共振系统就是建立在均线之上：</p><p>二. 趋势的中期，（太懒了，不想写了），不过上面方法依然可用，在大势中的回调使用。。</p><p>三.识别趋势的结束，（太懒了，不想写了）上面方法依然可用。。</p>',43)]))}const K=a(o,[["render",n]]);export{m as __pageData,K as default};
